      var p=previous.rabbits[j];
      if(!p||p.active!==true||p.state!=='Grazing'||p.foodAvailable!==true||p.directAlarm===true||p.socialCue||p.refugeCue||![p.x,p.z].every(Number.isFinite))return null;
